
let step=0,universe='bloom';const names=obUniverses.names;obUniverses.read().then(id=>{if(id&&step<3)universe=id});const steps=[['Meet Omnibloom','One suite for browsing, downloads, files and controllers.'],['Make yourself at home','Use the D-pad to move, Select to open and Back to return.'],['Your console stays protected','Web pages cannot reach console administration ports; trusted app pages use a narrow allowlist.'],['Pick your universe','Choose a look now; you can change it later.']];
function draw(){const [title,copy]=steps[step];document.getElementById('step-title').textContent=title;document.getElementById('step-count').textContent=(step+1)+' of 4';const box=document.getElementById('step');box.replaceChildren();const p=document.createElement('p');p.textContent=copy;box.append(p);if(step===0){const h=document.createElement('h2');h.textContent='Potential birth from possibility';box.append(h);const art=document.createElement('img');art.className='welcome-bloom';art.src='../shared/art/universes/bloom.webp';art.alt='Original Bloom universe artwork';box.append(art)}if(step===1){const h=document.createElement('div');h.className='grid two';['D-pad · Move','× / A · Select','○ / B · Back','L1/R1 · Switch tabs'].forEach(t=>{const p=document.createElement('div');p.className='card';p.textContent=t;h.append(p)});box.append(h)}if(step===2){const a=document.createElement('a');a.href='../info/index.html?state=blocked';a.textContent='About blocked connections';box.append(a);const p=document.createElement('p');p.textContent='This preview saves your choices and recent sites on this device.';box.append(p)}if(step===3){const label=document.createElement('label');label.textContent='Universe';const select=document.createElement('select');select.id='universe';select.setAttribute('aria-label','Universe');names.forEach(n=>select.add(new Option(n,n.toLowerCase())));select.value=universe;select.onchange=()=>universe=select.value;label.append(select);box.append(label)}document.getElementById('previous').disabled=step===0;document.getElementById('next').textContent=step===3?'Start exploring':'Continue'}
document.getElementById('next').onclick=async()=>{if(step<3){step++;draw();obUI.focus(step===3?document.getElementById('universe'):document.getElementById('next'))}else{try{localStorage.setItem('ob.welcome.v1','done');localStorage.setItem('ob.universe',universe)}catch(e){}await obUniverses.write(universe);location.href='../start/index.html'}};document.getElementById('previous').onclick=()=>{if(step){step--;draw();obUI.focus(document.getElementById('next'))}};window.obBack=()=>{if(!step)return false;step--;draw();obUI.focus(document.getElementById('next'));return true};draw();
if(new URLSearchParams(location.search).get('firstRun')==='1'){try{if(localStorage.getItem('ob.welcome.v1')==='done')location.replace('../start/index.html')}catch(e){}}
